import static com.coraline.feast.OtherMotherLoopState.Phase.*;

/** One owner-scoped outing, sharing the visit ledger and the real family/pursuit actors. */
@net.minecraftforge.fml.common.Mod.EventBusSubscriber(modid="coraline")
public final class FamilyOuting {
    public enum Subtype { PICNIC,FISHING_TRIP,STARGAZING,WOODLAND_WALK,BOAT_RIDE }
    public record Definition(String name,String landmark,String voice,int duration,boolean water,Item reward){}
    public static final Map<Subtype,Definition> REGISTRY=new EnumMap<>(Subtype.class);
    static {
        register(Subtype.PICNIC,new Definition("Family Picnic","Flower Meadow","picnic",3600,false,Items.COOKIE));
        register(Subtype.FISHING_TRIP,new Definition("Family Fishing Trip","Lakeside Dock","fishing",4200,true,Items.SALMON));
        register(Subtype.STARGAZING,new Definition("Family Stargazing","Hilltop Observatory","stargazing",3600,false,Items.PAPER));
        register(Subtype.WOODLAND_WALK,new Definition("Woodland Nature Walk","Forest Trailhead","woodland",4800,false,Items.ALLIUM));
        register(Subtype.BOAT_RIDE,new Definition("Lakeside Boat Ride","Moonlit Boathouse","boat",3600,true,Items.NAUTILUS_SHELL));
    }
    public static void register(Subtype id,Definition definition){REGISTRY.put(id,definition);}
    public static Subtype subtype(VisitData.Scene s){try{return Subtype.valueOf(s.loop.event.getString("OutingSubtype"));}catch(IllegalArgumentException e){return Subtype.PICNIC;}}
    static Definition definition(VisitData.Scene s){return REGISTRY.get(subtype(s));}
    public static OtherMotherDialogue.Pool pool(String category,OtherMotherWelcome.State state){return new OtherMotherDialogue.Pool("events/family_outing/"+category+"/"+SecretDialogue.stateId(state),2);}
    static OtherMotherDialogue.Pool destination(Subtype type){return new OtherMotherDialogue.Pool("events/family_outing/destination/"+REGISTRY.get(type).voice,2);}
    public static List<OtherMotherDialogue.Pool> pools(){var out=new ArrayList<OtherMotherDialogue.Pool>();for(var category:List.of("invitation","ontime","late","search","finish"))for(var state:OtherMotherWelcome.State.values())out.add(pool(category,state));for(var type:REGISTRY.keySet())out.add(destination(type));return out;}
    public static List<String> fatherVoices(){var voices=new ArrayList<String>();for(var type:REGISTRY.keySet())for(var phase:List.of("start","interaction","finish"))voices.add("father_outing_"+REGISTRY.get(type).voice+"_father_"+phase);return voices;}
    static String fatherVoice(VisitData.Scene s,String phase){return "father_outing_"+definition(s).voice+"_father_"+phase;}
    static boolean prepare(ServerPlayer p,VisitData.Scene s,Subtype forced){
        for(String key:new HashSet<>(s.loop.event.getAllKeys()))if(key.startsWith("Picnic"))s.loop.event.remove(key);
        var n=s.loop.event;n.putLong("OutingSeed",p.getRandom().nextLong());var choices=new ArrayList<>(REGISTRY.keySet());Collections.shuffle(choices,new Random(n.getLong("OutingSeed")));String previous=s.loop.secrets.world.getString("LastFamilyOuting");choices.sort(Comparator.comparing(t->t.name().equals(previous)));if(forced!=null){choices.remove(forced);choices.add(0,forced);}
        for(var type:choices){var site=OutingSites.choose(p,s,type);if(site==null)continue;n.putString("OutingSubtype",type.name());n.put("OutingSite",site.save());n.putBoolean("OutingPending",true);n.putString("OutingState","INVITATION");s.loop.secrets.world.putString("LastFamilyOuting",type.name());EventChunks.hold(p,s,site.approach());decorate(p,s);OtherMotherLoop.changed(p);return true;}return false;
    }
    static void afterInvitation(ServerPlayer p,VisitData.Scene s){OtherMotherLoop.phase(p,s,OUTING_DESTINATION);}
    public static void beginWindow(ServerPlayer p,VisitData.Scene s){var n=s.loop.event;n.putInt("ArrivalRemaining",6000);n.putBoolean("GraceRolled",false);n.putBoolean("Searching",false);n.putInt("ParentTravel",0);n.putString("OutingState","TRAVEL_WINDOW");OtherMotherLoop.phase(p,s,OUTING_WAIT);var d=VisitEvents.father(p,s);var m=MotherSearch.mother(p);if(d!=null)d.stopRiding();if(m!=null)m.stopRiding();}
    static boolean tick(ServerPlayer p,VisitData.Scene s){
        var n=s.loop.event;var site=OutingSites.current(s);if(site==null){abort(p,s);return true;}if(!n.getBoolean("OutingPending"))return true;
        if(s.loop.phase==OUTING_DESTINATION){if(VisitEvents.speak(p,s,destination(subtype(s))))beginWindow(p,s);return true;}
        if(s.loop.phase==OUTING_WAIT){
            if(p.distanceToSqr(site.arrival().getCenter())<=144)bringParentsToArrival(p,s);
            n.putInt("ParentTravel",n.getInt("ParentTravel")+1);boolean ready=parentsReady(p,s);n.putBoolean("ParentsReady",ready);if(!ready){if(n.getInt("ParentTravel")>3600)abort(p,s);return true;}
            if(n.getBoolean("Resuming")){int ticks=n.getInt("ResumeWait")+1;n.putInt("ResumeWait",ticks);if(ticks>12000)abort(p,s);return true;}
            int remaining=n.getInt("ArrivalRemaining");if(remaining>0){n.putInt("ArrivalRemaining",remaining-1);return true;}
            if(!n.getBoolean("GraceRolled")){n.putBoolean("GraceRolled",true);n.putInt("GraceRemaining",FamilyDinner.graceTicks(s.loop.suspicion,p.getRandom().nextDouble()));n.putString("OutingState","LATE_GRACE");OtherMotherLoop.changed(p);return true;}
            int grace=n.getInt("GraceRemaining");if(grace>0){n.putInt("GraceRemaining",grace-1);return true;}
            if(!n.getBoolean("Searching")&&VisitEvents.speak(p,s,pool("search",SecretDialogue.state(p)))){n.putBoolean("Searching",true);n.putString("OutingState","SEARCHING");s.loop.secrets.search=SecretsState.Search.SEARCHING;s.loop.secrets.target=p.blockPosition();OtherMotherLoop.changed(p);}return true;
        }
        if(s.loop.phase==OUTING_GREETING){if(!n.getBoolean("MotherGreetingDone")){if(VisitEvents.speak(p,s,pool(n.getBoolean("Late")?"late":"ontime",OtherMotherWelcome.State.fromId(n.getString("ArrivalState")))))n.putBoolean("MotherGreetingDone",true);return true;}if(!FamilyDinner.fatherSpeech(p,s,fatherVoice(s,"start")))return true;beginExperience(p,s);return true;}
        if(s.loop.phase==OUTING_ACTIVE){
            if(p.distanceToSqr(site.arrival().getCenter())>6400&&subtype(s)!=Subtype.WOODLAND_WALK){int away=n.getInt("OutingAway")+1;n.putInt("OutingAway",away);if(away>1200){release(p,s);n.putInt("OutingReturn",0);OtherMotherLoop.phase(p,s,OUTING_RETURN);}return true;}n.putInt("OutingAway",0);
            int elapsed=n.getInt("OutingElapsed")+1;n.putInt("OutingElapsed",elapsed);animate(p,s,elapsed);if(n.getBoolean("OutingFailed")){abort(p,s);return true;}
            if(!n.getBoolean("InteractionSpoken")&&elapsed>=(subtype(s)==Subtype.STARGAZING?1:600)){if(!FamilyDinner.fatherSpeech(p,s,fatherVoice(s,"interaction")))return true;n.putBoolean("InteractionSpoken",true);}
            if(subtype(s)==Subtype.PICNIC?picnicFinished(n):subtype(s)==Subtype.STARGAZING?n.getInt("StarsObserved")>=ConstellationPuzzle.ROUNDS:elapsed>=definition(s).duration){release(p,s);n.putBoolean("FatherFinished",false);OtherMotherLoop.phase(p,s,OUTING_FINISH);}return true;
        }
        if(s.loop.phase==OUTING_RETURN){if(p.distanceToSqr(site.arrival().getCenter())<256){OtherMotherLoop.phase(p,s,OUTING_ACTIVE);return true;}int ticks=n.getInt("OutingReturn")+1;n.putInt("OutingReturn",ticks);if(ticks>6000)abort(p,s);return true;}
        if(s.loop.phase==OUTING_FINISH){if(!n.getBoolean("FatherFinished")){if(FamilyDinner.fatherSpeech(p,s,fatherVoice(s,"finish")))n.putBoolean("FatherFinished",true);return true;}if(!VisitEvents.speak(p,s,pool("finish",SecretDialogue.state(p))))return true;if(!n.getBoolean("CompletionAwarded")){n.putBoolean("CompletionAwarded",true);OtherMotherLoop.relationship(p,s.loop.trust+VisitConfig.OUTING_COMPLETE.get().floatValue(),s.loop.suspicion);reward(p,s);}n.putBoolean("OutingPending",false);n.putString("OutingState","COMPLETED");VisitEvents.next(p,s,false);return true;}return true;
    }
    public static boolean join(ServerPlayer p,VisitData.Scene s,ParentEntity actor){var n=s.loop.event;var site=OutingSites.current(s);if(VisitEvents.type(s)!=VisitEvents.Type.FAMILY_OUTING||s.loop.phase!=OUTING_WAIT||site==null||!p.getUUID().equals(s.owner)||!Objects.equals(actor.getUUID(),actor.isMom()?s.mom:s.dad)||actor.distanceToSqr(p)>25||p.distanceToSqr(site.arrival().getCenter())>64||!parentsReady(p,s)||s.loop.secrets.searching()||n.getBoolean("Searching")||SecretDialogue.busy(p))return false;
        boolean late=n.getInt("ArrivalRemaining")<=0||n.getBoolean("Resuming");n.putBoolean("Late",late);n.putString("ArrivalState",SecretDialogue.state(p).id());n.putInt("ArrivalRemaining",0);n.putInt("GraceRemaining",0);n.putBoolean("MotherGreetingDone",false);if(!n.getBoolean("ArrivalAwarded")&&!n.getBoolean("Resuming"))OtherMotherLoop.relationship(p,s.loop.trust+(late?VisitConfig.OUTING_LATE_TRUST:VisitConfig.OUTING_ON_TIME).get().floatValue(),s.loop.suspicion+(late?VisitConfig.OUTING_LATE_SUSPICION.get().floatValue():0));n.putBoolean("ArrivalAwarded",true);n.putString("OutingState","WAITING_FOR_JOIN");OtherMotherLoop.phase(p,s,OUTING_GREETING);return true;}
    static boolean parentsReady(ServerPlayer p,VisitData.Scene s){var site=OutingSites.current(s);var m=MotherSearch.mother(p);var d=VisitEvents.father(p,s);return site!=null&&m!=null&&d!=null&&m.distanceToSqr(site.arrival().getCenter())<64&&d.distanceToSqr(site.arrival().getCenter())<64;}
    static void bringParentsToArrival(ServerPlayer p,VisitData.Scene s){
        for(var parent:new ParentEntity[]{MotherSearch.mother(p),VisitEvents.father(p,s)})if(parent!=null){var target=waiting(s,parent.isMom());if(parent.distanceToSqr(target)<=16)continue;
            var safe=Reconciliation.safe(p,BlockPos.containing(target));if(safe==null)continue;var feet=Vec3.atBottomCenterOf(safe);if(!p.serverLevel().noCollision(parent,parent.getDimensions(parent.getPose()).makeBoundingBox(feet)))continue;
            parent.stopRiding();parent.getNavigation().stop();parent.teleportTo(feet.x,feet.y,feet.z);parent.setDeltaMovement(Vec3.ZERO);parent.fallDistance=0;
        }
    }
    public static boolean resume(ServerPlayer p){var s=OtherMotherLoop.scene(p);if(s==null||VisitEvents.type(s)!=VisitEvents.Type.FAMILY_OUTING||!s.loop.event.getBoolean("OutingPending"))return false;var n=s.loop.event;release(p,s);for(String k:List.of("Voice","Sound","IntroElapsed","VoiceFinished","FatherVoice","FatherVoiceElapsed","FatherVoiceFinished"))n.remove(k);n.putBoolean("Resuming",true);n.putBoolean("Searching",false);n.putInt("ResumeWait",0);n.putInt("ArrivalRemaining",0);n.putInt("ParentTravel",0);n.putString("OutingState","WAITING_FOR_JOIN");OtherMotherLoop.phase(p,s,OUTING_WAIT);return true;}
    static void abort(ServerPlayer p,VisitData.Scene s){release(p,s);s.loop.event.putBoolean("OutingPending",false);s.loop.event.putString("OutingState","CANCELLED");VisitAudio.caption(p,"Family outing","The outing has ended. Your family is returning to the house.",80);VisitEvents.next(p,s,true);}
    static Vec3 waiting(VisitData.Scene s,boolean mom){var site=OutingSites.current(s);return site==null?Vec3.ZERO:Vec3.atBottomCenterOf(site.arrival()).add(mom?-1.5:1.5,0,0);}
    static void control(ParentEntity parent,ServerPlayer p,VisitData.Scene s){
        var site=OutingSites.current(s);if(site==null)return;FamilyDinner.finishBiteIfDone(parent,p);parent.setMaxUpStep(1.05F);if(s.loop.phase==EVENT_INTRO||s.loop.phase==OUTING_DESTINATION){parent.getNavigation().stop();return;}
        if(parent.isPassenger()){parent.getNavigation().stop();if(subtype(s)==Subtype.STARGAZING){parent.setXRot(-55);parent.setYHeadRot(parent.getYRot()+(float)Math.sin(parent.tickCount*.025)*30);}else parent.lookAtStoryPlayer(p);return;}
        Vec3 target=waiting(s,parent.isMom());
        if(s.loop.phase==OUTING_ACTIVE&&subtype(s)==Subtype.WOODLAND_WALK&&!site.walk().isEmpty()){int index=Math.min(s.loop.event.getInt("WalkStop"),site.walk().size()-1);target=Vec3.atBottomCenterOf(site.walk().get(index)).add(parent.isMom()?-.7:.7,0,0);if(p.distanceToSqr(target)>324){parent.getNavigation().stop();parent.lookAtStoryPlayer(p);return;}}
        else if(s.loop.phase==OUTING_ACTIVE&&(subtype(s)==Subtype.PICNIC||subtype(s)==Subtype.STARGAZING)){var chair=prop(p,s,ScenePropEntity.CHAIR,parent.isMom()?1:2);if(chair!=null){SupperSeating.approach(parent,chair);return;}}
        if(parent.distanceToSqr(target)>4){
            var data=parent.getPersistentData();int stalled=data.getInt("OutingStalled")+1;if(parent.position().distanceToSqr(new Vec3(data.getDouble("OutingLastX"),data.getDouble("OutingLastY"),data.getDouble("OutingLastZ")))>.25){stalled=0;data.putDouble("OutingLastX",parent.getX());data.putDouble("OutingLastY",parent.getY());data.putDouble("OutingLastZ",parent.getZ());}data.putInt("OutingStalled",stalled);
            Vec3 step=target;double best=Double.MAX_VALUE;int closest=0;for(int i=0;i<site.approach().size();i++){double d=parent.distanceToSqr(site.approach().get(i).getCenter());if(d<best){best=d;closest=i;}}if(best<400&&parent.distanceToSqr(target)>144&&s.loop.phase!=OUTING_ACTIVE)step=Vec3.atBottomCenterOf(site.approach().get(Math.min(site.approach().size()-1,closest+9)));
            if(parent.tickCount%20==0)parent.getNavigation().moveTo(step.x,step.y,step.z,1.05);
            // Only unseen recovery, on proven safe footing, with no duplicate actors.
            if((stalled>200||s.loop.event.getInt("ParentTravel")>1200)&&!p.hasLineOfSight(parent)&&p.distanceToSqr(target)>256&&p.serverLevel().noCollision(parent,parent.getDimensions(parent.getPose()).makeBoundingBox(target))){parent.teleportTo(target.x,target.y,target.z);parent.getNavigation().stop();data.putInt("OutingStalled",0);}
        }else{parent.getNavigation().stop();parent.lookAtStoryPlayer(p);}
    }
    static ScenePropEntity prop(ServerPlayer p,VisitData.Scene s,int kind,int slot){return VisitEvents.props(p,s).stream().filter(e->e.kind()==kind&&e.slot==slot).findFirst().orElse(null);}
    static ScenePropEntity add(ServerPlayer p,VisitData.Scene s,int kind,Vec3 at,int slot){var e=VisitEvents.prop(p,s,kind,at,slot);e.setCustomName(Component.literal(definition(s).landmark));return e;}
    static void decorate(ServerPlayer p,VisitData.Scene s){var site=OutingSites.current(s);var at=Vec3.atBottomCenterOf(site.arrival());var d=definition(s);add(p,s,ScenePropEntity.OUTING_SCENERY,at,subtype(s).ordinal());if(subtype(s)==Subtype.PICNIC||subtype(s)==Subtype.WOODLAND_WALK)cherryTrees(p,s);
        if(subtype(s)==Subtype.PICNIC){add(p,s,ScenePropEntity.PICNIC_BASKET,at.add(0,0,2),0);for(int i=0;i<3;i++){var plate=add(p,s,ScenePropEntity.PLATE,at.add(i-1,.14,0),i);plate.food(0,new ItemStack(i==0?Items.BREAD:i==1?Items.APPLE:Items.COOKIE,2));}add(p,s,ScenePropEntity.GLASS,at.add(.7,.14,-.8),0).food(0,new ItemStack(Items.POTION));}
        if(subtype(s)==Subtype.PICNIC||subtype(s)==Subtype.STARGAZING){for(int i=0;i<3;i++){var chair=add(p,s,ScenePropEntity.CHAIR,at.add(i==0?0:i==1?-2:2,0,i==0?-2:1),i);chair.setYRot(i==0?0:i==1?-90:90);}}
        if(subtype(s)==Subtype.STARGAZING)add(p,s,ScenePropEntity.OUTING_TELESCOPE,at.add(0,0,3),0);
        if(d.water){var tackle=add(p,s,ScenePropEntity.OUTING_TACKLE,at.add(0,0,2),0);tackle.food(0,new ItemStack(Items.FISHING_ROD));dock(p,s);}
        if(subtype(s)==Subtype.WOODLAND_WALK)for(int i=0;i<site.walk().size();i++){var q=site.walk().get(i);var foot=OutingSites.surface(p.serverLevel(),q.getX()+2,q.getZ());if(foot!=null&&OutingSites.natural(p.serverLevel(),foot))add(p,s,ScenePropEntity.OUTING_LANDMARK,Vec3.atBottomCenterOf(foot),i);}
    }
    static void beginExperience(ServerPlayer p,VisitData.Scene s){var n=s.loop.event;OtherMotherLoop.phase(p,s,OUTING_ACTIVE);n.putString("OutingState","OUTING_ACTIVE");if(!n.getBoolean("ExperienceStarted")){n.putInt("OutingElapsed",0);n.putInt("WalkStop",0);n.putInt("WalkRest",0);n.putBoolean("ExperienceStarted",true);}var at=Vec3.atBottomCenterOf(OutingSites.current(s).arrival());
        if(subtype(s)==Subtype.PICNIC){var basket=prop(p,s,ScenePropEntity.PICNIC_BASKET,0);if(basket!=null)basket.mode(n.getBoolean("PicnicUnpacked")?1:0);picnicFlowers(p,s);}
        if(subtype(s)==Subtype.STARGAZING){var chair=prop(p,s,ScenePropEntity.CHAIR,0);if(chair!=null&&!chair.isVehicle()&&p.distanceToSqr(chair)<25)p.startRiding(chair,true);}
        if(subtype(s)==Subtype.FISHING_TRIP&&!n.getBoolean("RodIssued")){var rod=new ItemStack(Items.FISHING_ROD);rod.enchant(Enchantments.FISHING_SPEED,3);rod.getOrCreateTag().putUUID("OutingOwner",p.getUUID());rod.getTag().putInt("OutingSerial",n.getInt("Serial"));if(p.getInventory().add(rod))n.putBoolean("RodIssued",true);else p.displayClientMessage(Component.literal("Make one inventory slot available, then use the tackle box."),true);}
        if(subtype(s)==Subtype.BOAT_RIDE)board(p,s);
    }
    static void animate(ServerPlayer p,VisitData.Scene s,int elapsed){var n=s.loop.event;var site=OutingSites.current(s);var at=site.arrival();var l=p.serverLevel();
        if(elapsed%20==0)l.sendParticles(ParticleTypes.GLOW,at.getX()+p.getRandom().nextInt(13)-6,at.getY()+1+p.getRandom().nextFloat()*2,at.getZ()+p.getRandom().nextInt(13)-6,2,.3,.3,.3,.01);
        var mom=MotherSearch.mother(p);var dad=VisitEvents.father(p,s);
        switch(subtype(s)){
            case PICNIC->{if(elapsed%40==0)p.displayClientMessage(Component.literal(picnicObjective(n)),true);}
            case FISHING_TRIP->{for(var parent:new ParentEntity[]{mom,dad})if(parent!=null){equip(parent,new ItemStack(Items.FISHING_ROD));if(elapsed%180==20){parent.swing(net.minecraft.world.InteractionHand.MAIN_HAND);l.playSound(null,parent.blockPosition(),SoundEvents.FISHING_BOBBER_THROW,SoundSource.NEUTRAL,.5F,1);var bobber=prop(p,s,ScenePropEntity.OUTING_BOBBER,parent.isMom()?1:2);if(bobber==null)bobber=add(p,s,ScenePropEntity.OUTING_BOBBER,site.water().get(parent.isMom()?0:8),parent.isMom()?1:2);bobber.mode(0);var line=new CompoundTag();line.putInt("AnglerId",parent.getId());line.putUUID("AnglerUUID",parent.getUUID());bobber.cakeData(line);}if(elapsed%180==140){parent.swing(net.minecraft.world.InteractionHand.MAIN_HAND);var water=site.water().get(parent.isMom()?0:8);l.sendParticles(new ItemParticleOption(ParticleTypes.ITEM,new ItemStack(Items.COD)),water.x,water.y+1,water.z,6,.15,.6,.15,.1);l.playSound(null,parent.blockPosition(),SoundEvents.FISHING_BOBBER_RETRIEVE,SoundSource.NEUTRAL,.5F,1);var bobber=prop(p,s,ScenePropEntity.OUTING_BOBBER,parent.isMom()?1:2);if(bobber!=null)bobber.mode(1);}}}
            case STARGAZING->{if(elapsed%150==0)for(var parent:new ParentEntity[]{mom,dad})if(parent!=null){parent.setXRot(-50);parent.swing(net.minecraft.world.InteractionHand.MAIN_HAND);}}
            case WOODLAND_WALK->{int stop=Math.min(n.getInt("WalkStop"),site.walk().size()-1);var target=site.walk().get(stop).getCenter();if(mom!=null&&dad!=null&&mom.distanceToSqr(target)<16&&dad.distanceToSqr(target)<16&&p.distanceToSqr(target)<144){int rest=n.getInt("WalkRest")+1;n.putInt("WalkRest",rest);if(rest>=450&&stop<site.walk().size()-1){n.putInt("WalkStop",stop+1);n.putInt("WalkRest",0);}}}
            case BOAT_RIDE->sail(p,s,elapsed);
        }
    }
    static void dock(ServerPlayer p,VisitData.Scene s){var site=OutingSites.current(s);if(site==null||site.water().isEmpty())return;var from=Vec3.atBottomCenterOf(site.arrival());var toward=site.water().get(0).subtract(from).multiply(1,0,1);int steps=Math.max(0,(int)toward.length()-3);var dir=toward.normalize();var blocks=new ListTag();var seen=new HashSet<BlockPos>();for(int i=0;i<=steps;i++){var at=BlockPos.containing(from.add(dir.scale(i))).below();for(int side=-1;side<=1;side++){var q=at.offset(Math.abs(dir.x)<.5?side:0,0,Math.abs(dir.x)>=.5?side:0);if(!seen.add(q))continue;var old=p.serverLevel().getBlockState(q);if(old.hasBlockEntity()||!old.getFluidState().is(net.minecraft.tags.FluidTags.WATER)&&!old.is(net.minecraft.tags.BlockTags.DIRT)&&!old.is(net.minecraft.world.level.block.Blocks.GRASS_BLOCK))continue;var tag=new CompoundTag();tag.putLong("Pos",q.asLong());tag.put("Original",NbtUtils.writeBlockState(old));tag.put("Placed",NbtUtils.writeBlockState(net.minecraft.world.level.block.Blocks.SPRUCE_PLANKS.defaultBlockState()));blocks.add(tag);p.serverLevel().setBlock(q,net.minecraft.world.level.block.Blocks.SPRUCE_PLANKS.defaultBlockState(),2);}}s.loop.event.put("OutingBlocks",blocks);}
    static void restoreDock(ServerPlayer p,VisitData.Scene s){var level=p.server.getLevel(OtherWorld.KEY);if(level==null)return;var registry=level.holderLookup(net.minecraft.core.registries.Registries.BLOCK);for(var entry:s.loop.event.getList("OutingBlocks",10)){var n=(CompoundTag)entry;var at=BlockPos.of(n.getLong("Pos"));if(level.getBlockState(at).equals(NbtUtils.readBlockState(registry,n.getCompound("Placed"))))level.setBlock(at,NbtUtils.readBlockState(registry,n.getCompound("Original")),2);}s.loop.event.remove("OutingBlocks");}
    static void cherryTrees(ServerPlayer p,VisitData.Scene s){
        var site=OutingSites.current(s);var level=p.serverLevel();var blocks=s.loop.event.getList("OutingBlocks",10);
        for(int side:new int[]{-1,1}){var base=site.arrival().offset(side*5,0,4);if(!OutingSites.natural(level,base))continue;var wanted=new LinkedHashMap<BlockPos,net.minecraft.world.level.block.state.BlockState>();
            for(int y=0;y<4;y++)wanted.put(base.above(y),net.minecraft.world.level.block.Blocks.CHERRY_LOG.defaultBlockState());
            for(int y=3;y<=4;y++)for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)if(!wanted.containsKey(base.offset(x,y,z)))wanted.put(base.offset(x,y,z),net.minecraft.world.level.block.Blocks.CHERRY_LEAVES.defaultBlockState().setValue(net.minecraft.world.level.block.LeavesBlock.PERSISTENT,true));
            if(wanted.keySet().stream().anyMatch(at->!level.getBlockState(at).canBeReplaced()||level.getBlockState(at).hasBlockEntity()))continue;
            for(var entry:wanted.entrySet()){var tag=new CompoundTag();tag.putLong("Pos",entry.getKey().asLong());tag.put("Original",NbtUtils.writeBlockState(level.getBlockState(entry.getKey())));tag.put("Placed",NbtUtils.writeBlockState(entry.getValue()));blocks.add(tag);level.setBlock(entry.getKey(),entry.getValue(),2);}
        }s.loop.event.put("OutingBlocks",blocks);
    }
    static void equip(ParentEntity parent,ItemStack stack){var n=parent.getPersistentData();if(!n.contains("OutingOldHand"))n.put("OutingOldHand",parent.getMainHandItem().save(new CompoundTag()));if(!parent.getMainHandItem().is(stack.getItem()))parent.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,stack);}
    public static boolean interact(ServerPlayer p,ScenePropEntity e){var s=OtherMotherLoop.active(p);if(s==null||VisitEvents.type(s)!=VisitEvents.Type.FAMILY_OUTING||!e.getPersistentData().contains("VisitEventSerial"))return false;if(!p.getUUID().equals(e.owner)||e.storyDoor==null||!e.storyDoor.equals(s.door)||e.getPersistentData().getInt("VisitEventSerial")!=s.loop.event.getInt("Serial")||e.distanceToSqr(p)>36||s.loop.secrets.searching()||s.loop.phase!=OUTING_ACTIVE)return true;var n=s.loop.event;
        if(subtype(s)==Subtype.PICNIC&&picnicInteract(p,s,e))return true;
        if(e.kind()==ScenePropEntity.CHAIR&&e.slot==0&&!e.isVehicle())p.startRiding(e,true);
        if(e.kind()==ScenePropEntity.PLATE){if(p.isShiftKeyDown()&&!n.getBoolean("OutingPassed")){n.putBoolean("OutingPassed",true);var dad=VisitEvents.father(p,s);if(dad!=null)FamilyDinner.bite(p,e,dad);positive(p,s);VisitAudio.caption(p,"Other Father","Thank you, kiddo!",60);}else if(OtherMotherLoop.now(p)>=n.getLong("BiteAfter")){n.putLong("BiteAfter",OtherMotherLoop.now(p)+30);FamilyDinner.bite(p,e,p);}}
        if(e.kind()==ScenePropEntity.GLASS&&!e.food(0).isEmpty())FamilyDinner.drink(p,e,p);
        if(e.kind()==ScenePropEntity.OUTING_TACKLE&&!n.getBoolean("RodIssued")&&subtype(s)==Subtype.FISHING_TRIP)beginExperience(p,s);
        if(e.kind()==ScenePropEntity.OUTING_TELESCOPE&&n.getInt("StarsObserved")<ConstellationPuzzle.ROUNDS){if(n.getBoolean("InteractionSpoken"))openTelescope(p,s,false);else p.displayClientMessage(Component.literal("Listen to Other Father before using the telescope."),true);}
        if(e.kind()==ScenePropEntity.OUTING_LANDMARK&&!n.getBoolean("FlowerPicked")){n.putBoolean("FlowerPicked",true);give(p,new ItemStack(Items.ALLIUM));positive(p,s);p.displayClientMessage(Component.literal("A moonlit flower from your family walk."),true);}
        return true;
    }
    static boolean picnicFinished(CompoundTag n){return n.getBoolean("PicnicPacked");}
    static String picnicObjective(CompoundTag n){
        if(!n.getBoolean("PicnicUnpacked"))return "Open the basket and unpack the picnic";
        if(n.getInt("PicnicFlowers")!=3)return "Collect the two flower arrangements beside the blanket";
        if(n.getInt("PicnicServed")!=3)return (n.getInt("PicnicServed")&1)==0?"Serve Mother's apple plate":"Serve Father's cookie plate";
        if(!n.getBoolean("PicnicTasted"))return "Try your bread and take a drink";
        return "Pack the basket when you're ready to finish";
    }
    static void picnicFlowers(ServerPlayer p,VisitData.Scene s){
        var site=OutingSites.current(s);for(int slot=100;slot<=101;slot++){if(prop(p,s,ScenePropEntity.OUTING_LANDMARK,slot)!=null)continue;int direction=slot==100?-1:1;for(int offset=6;offset<=10;offset++){var at=OutingSites.surface(p.serverLevel(),site.arrival().getX()+direction*offset,site.arrival().getZ()+4);if(at!=null&&OutingSites.feet(p.serverLevel(),at)){add(p,s,ScenePropEntity.OUTING_LANDMARK,Vec3.atBottomCenterOf(at),slot);break;}}}
    }
    static boolean picnicInteract(ServerPlayer p,VisitData.Scene s,ScenePropEntity e){
        var n=s.loop.event;
        if(e.kind()==ScenePropEntity.PICNIC_BASKET){if(!n.getBoolean("PicnicUnpacked")){n.putBoolean("PicnicUnpacked",true);e.mode(1);}else if(n.getInt("PicnicFlowers")==3&&n.getInt("PicnicServed")==3&&n.getBoolean("PicnicTasted")){n.putBoolean("PicnicPacked",true);e.mode(0);positive(p,s);}p.displayClientMessage(Component.literal(picnicObjective(n)),true);OtherMotherLoop.changed(p);return true;}
        if(!n.getBoolean("PicnicUnpacked"))return e.kind()==ScenePropEntity.PLATE||e.kind()==ScenePropEntity.GLASS||e.kind()==ScenePropEntity.OUTING_LANDMARK;
        if(e.kind()==ScenePropEntity.OUTING_LANDMARK&&e.slot>=100&&e.slot<=101){int mask=1<<(e.slot-100);if((n.getInt("PicnicFlowers")&mask)==0){n.putInt("PicnicFlowers",n.getInt("PicnicFlowers")|mask);e.mode(1);p.playNotifySound(SoundEvents.AMETHYST_BLOCK_CHIME,SoundSource.NEUTRAL,.4F,1.2F);}p.displayClientMessage(Component.literal(picnicObjective(n)),true);OtherMotherLoop.changed(p);return true;}
        if(e.kind()==ScenePropEntity.PLATE&&e.slot>0&&e.slot<=2){int mask=1<<(e.slot-1);if(n.getInt("PicnicFlowers")==3&&(n.getInt("PicnicServed")&mask)==0){var parent=e.slot==1?MotherSearch.mother(p):VisitEvents.father(p,s);if(parent!=null){FamilyDinner.bite(p,e,parent);n.putInt("PicnicServed",n.getInt("PicnicServed")|mask);}}p.displayClientMessage(Component.literal(picnicObjective(n)),true);OtherMotherLoop.changed(p);return true;}
        if(e.kind()==ScenePropEntity.PLATE&&e.slot==0)n.putBoolean("PicnicBread",true);
        if(e.kind()==ScenePropEntity.GLASS)n.putBoolean("PicnicDrink",true);
        n.putBoolean("PicnicTasted",n.getBoolean("PicnicBread")&&n.getBoolean("PicnicDrink"));return false;
    }
    static void positive(ServerPlayer p,VisitData.Scene s){if(s.loop.event.getBoolean("OutingPositive"))return;s.loop.event.putBoolean("OutingPositive",true);OtherMotherLoop.relationship(p,s.loop.trust+VisitConfig.OUTING_POSITIVE.get().floatValue(),s.loop.suspicion);}
    static void openTelescope(ServerPlayer p,VisitData.Scene s,boolean retry){var n=s.loop.event;var packet=new CompoundTag();packet.putBoolean("OutingTelescope",true);packet.putInt("Observation",n.getInt("StarsObserved"));packet.putLong("Seed",n.getLong("OutingSeed"));packet.putBoolean("Retry",retry);packet.putBoolean("Complete",n.getInt("StarsObserved")>=ConstellationPuzzle.ROUNDS);packet.putUUID("Nonce",UUID.randomUUID());n.putUUID("TelescopeNonce",packet.getUUID("Nonce"));n.putInt("TelescopeObservation",packet.getInt("Observation"));SecretsNetwork.send(p,packet);}
    public static boolean choice(ServerPlayer p,UUID nonce,String answer){
        var s=OtherMotherLoop.active(p);if(s==null||VisitEvents.type(s)!=VisitEvents.Type.FAMILY_OUTING||!s.loop.event.hasUUID("TelescopeNonce")||!s.loop.event.getUUID("TelescopeNonce").equals(nonce))return false;
        var n=s.loop.event;boolean current=n.contains("TelescopeObservation")&&n.getInt("TelescopeObservation")==n.getInt("StarsObserved");n.remove("TelescopeNonce");n.remove("TelescopeObservation");
        var telescope=prop(p,s,ScenePropEntity.OUTING_TELESCOPE,0);if(!current||s.loop.phase!=OUTING_ACTIVE||!n.getBoolean("InteractionSpoken")||s.loop.secrets.searching()||telescope==null||telescope.distanceToSqr(p)>36||n.getInt("StarsObserved")>=ConstellationPuzzle.ROUNDS)return true;
        // Receive the actual choices, never a client assertion that the observation succeeded.
        if(!answer.matches("star_selection:(?:[0-9]|1[0-5])(?:,(?:[0-9]|1[0-5])){2,4}"))return true;
        var selected=new ArrayList<Integer>();for(String id:answer.substring("star_selection:".length()).split(","))selected.add(Integer.parseInt(id));
        boolean correct=ConstellationPuzzle.matches(n.getLong("OutingSeed"),n.getInt("StarsObserved"),selected);
        if(correct){n.putInt("StarsObserved",n.getInt("StarsObserved")+1);positive(p,s);p.playNotifySound(SoundEvents.AMETHYST_BLOCK_CHIME,SoundSource.NEUTRAL,.4F,1.3F);}openTelescope(p,s,!correct);OtherMotherLoop.changed(p);return true;
    }
    static void reward(ServerPlayer p,VisitData.Scene s){var n=s.loop.event;if(n.getBoolean("OutingRewardClaimed"))return;n.putBoolean("OutingRewardClaimed",true);var stack=new ItemStack(definition(s).reward,subtype(s)==Subtype.PICNIC?3:1);if(subtype(s)==Subtype.STARGAZING)stack.setHoverName(Component.literal("Family Constellation Chart"));give(p,stack);OtherMotherLoop.changed(p);}
    static void give(ServerPlayer p,ItemStack item){SecretTransactions.give(p,item);}
    static List<Boat> boats(ServerPlayer p,VisitData.Scene s){var site=OutingSites.current(s);return site==null?List.of():p.serverLevel().getEntitiesOfClass(Boat.class,new AABB(site.arrival()).inflate(80),b->b.getPersistentData().hasUUID("OutingOwner")&&p.getUUID().equals(b.getPersistentData().getUUID("OutingOwner"))&&b.getPersistentData().getInt("OutingSerial")==s.loop.event.getInt("Serial"));}
    static void board(ServerPlayer p,VisitData.Scene s){board(p,s,true);}
    static void board(ServerPlayer p,VisitData.Scene s,boolean allowOwnerBoarding){var site=OutingSites.current(s);if(site==null||site.water().size()<5)return;var dad=VisitEvents.father(p,s);var mom=MotherSearch.mother(p);if(dad==null||mom==null)return;var list=boats(p,s);for(int i=0;i<2;i++){final int boatSlot=i;if(list.stream().anyMatch(b->b.getPersistentData().getInt("OutingBoat")==boatSlot))continue;var at=boatTarget(site,i,s.loop.event.getInt("OutingElapsed"),definition(s).duration);var r=RealmData.get(p.server).realms.get(s.door);if(!OutingSites.waterSafe(p.serverLevel(),r,at.add(0,-.15,0))){s.loop.event.putBoolean("OutingFailed",true);return;}var b=new Boat(p.level(),at.x,at.y,at.z);b.setVariant(Boat.Type.SPRUCE);b.getPersistentData().putBoolean("CoralineDecoration",true);b.getPersistentData().putUUID("OutingOwner",p.getUUID());b.getPersistentData().putInt("OutingSerial",s.loop.event.getInt("Serial"));b.getPersistentData().putInt("OutingBoat",i);p.serverLevel().addFreshEntity(b);}for(var b:boats(p,s)){if(b.getPersistentData().getInt("OutingBoat")==0){dad.startRiding(b,true);}else{mom.startRiding(b,true);if(allowOwnerBoarding)p.startRiding(b,true);}}}
    static Vec3 boatTarget(OutingSites.Site site,int slot,int elapsed,int duration){double fraction=Math.max(0,Math.min(1,elapsed/(double)Math.max(1,duration-100)));double progress=(fraction*(site.water().size()-1)+slot*4)%site.water().size();int index=(int)progress;return site.water().get(index).lerp(site.water().get((index+1)%site.water().size()),progress-index).add(0,.15,0);}
    static void sail(ServerPlayer p,VisitData.Scene s,int elapsed){var site=OutingSites.current(s);var list=boats(p,s);if(list.size()!=2){board(p,s,false);return;}var r=RealmData.get(p.server).realms.get(s.door);for(var b:list){int slot=b.getPersistentData().getInt("OutingBoat");var target=boatTarget(site,slot,elapsed,definition(s).duration);if(!OutingSites.waterSafe(p.serverLevel(),r,target.add(0,-.15,0))){release(p,s);s.loop.event.putBoolean("OutingFailed",true);return;}var delta=target.subtract(b.position());if(delta.length()>3){release(p,s);s.loop.event.putBoolean("OutingFailed",true);return;}b.setDeltaMovement(delta.scale(.25).add(0,-b.getDeltaMovement().y,0));b.setYRot((float)Math.toDegrees(Math.atan2(-delta.x,delta.z)));b.setPaddleState(true,true);if(elapsed%400==0)p.serverLevel().sendParticles(ParticleTypes.SPLASH,target.x,target.y,target.z,8,1,.2,1,.05);if(!b.hasPassenger(p)&&slot==1){int away=s.loop.event.getInt("BoatAway")+1;s.loop.event.putInt("BoatAway",away);if(away>200){release(p,s);s.loop.event.putBoolean("OutingFailed",true);return;}}else if(slot==1)s.loop.event.putInt("BoatAway",0);}}
    static void release(ServerPlayer p,VisitData.Scene s){var site=OutingSites.current(s);if(site==null)return;for(var b:boats(p,s)){for(var rider:List.copyOf(b.getPassengers())){rider.stopRiding();var at=waiting(s,rider instanceof ParentEntity parent&&parent.isMom());if(p.serverLevel().noCollision(rider,rider.getDimensions(rider.getPose()).makeBoundingBox(at)))rider.teleportTo(at.x,at.y,at.z);}b.discard();}if(p.getVehicle() instanceof ScenePropEntity e&&p.getUUID().equals(e.owner))p.stopRiding();}
    static void cleanup(ServerPlayer p,VisitData.Scene s){release(p,s);for(var parent:new ParentEntity[]{MotherSearch.mother(p),VisitEvents.father(p,s)})if(parent!=null){var n=parent.getPersistentData();if(n.contains("OutingOldHand")){parent.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,ItemStack.of(n.getCompound("OutingOldHand")));n.remove("OutingOldHand");}n.remove("OutingStalled");}for(var stack:p.getInventory().items)if(ownedRod(p,s,stack))stack.setCount(0);for(var stack:p.getInventory().offhand)if(ownedRod(p,s,stack))stack.setCount(0);for(String key:List.of("OutingSite","OutingSubtype","OutingSeed","OutingPending","OutingState","OutingElapsed","OutingAway","OutingReturn","OutingPassed","OutingPositive","OutingRewardClaimed","StarsObserved","TelescopeNonce","TelescopeObservation","RodIssued","OutingFish","ExperienceStarted","InteractionSpoken","WalkStop","WalkRest","ParentsReady","ParentTravel","ResumeWait","FlowerPicked","BoatAway","OutingFailed"))s.loop.event.remove(key);}
    static boolean ownedRod(ServerPlayer p,VisitData.Scene s,ItemStack rod){return rod.is(Items.FISHING_ROD)&&rod.hasTag()&&rod.getTag().hasUUID("OutingOwner")&&p.getUUID().equals(rod.getTag().getUUID("OutingOwner"))&&rod.getTag().getInt("OutingSerial")==s.loop.event.getInt("Serial");}
    public static boolean allowHook(net.minecraft.world.entity.projectile.FishingHook hook){if(!(hook.getPlayerOwner() instanceof ServerPlayer p))return false;var s=OtherMotherLoop.active(p);return s!=null&&VisitEvents.type(s)==VisitEvents.Type.FAMILY_OUTING&&s.loop.phase==OUTING_ACTIVE&&subtype(s)==Subtype.FISHING_TRIP&&(ownedRod(p,s,p.getMainHandItem())||ownedRod(p,s,p.getOffhandItem()));}
    @net.minecraftforge.eventbus.api.SubscribeEvent public static void fished(net.minecraftforge.event.entity.player.ItemFishedEvent event){if(!(event.getEntity() instanceof ServerPlayer p))return;var s=OtherMotherLoop.active(p);if(s==null||!ownedRod(p,s,p.getMainHandItem())&&!ownedRod(p,s,p.getOffhandItem()))return;if(VisitEvents.type(s)!=VisitEvents.Type.FAMILY_OUTING||s.loop.phase!=OUTING_ACTIVE||subtype(s)!=Subtype.FISHING_TRIP||s.loop.secrets.searching()||s.loop.event.getInt("OutingFish")>=5){event.getDrops().clear();return;}event.getDrops().clear();event.getDrops().add(new ItemStack(p.getRandom().nextBoolean()?Items.COD:Items.SALMON));s.loop.event.putInt("OutingFish",s.loop.event.getInt("OutingFish")+1);positive(p,s);OtherMotherLoop.changed(p);}
    public static void debug(ServerPlayer p,String action){if(!p.hasPermissions(2)||!OtherWorld.isOther(p.level()))return;var s=OtherMotherLoop.active(p);if(s==null)return;String[] parts=action.split(",",2);String arg=parts.length>1?parts[1]:"";if(parts[0].equals("force")){VisitEvents.start(p,s,VisitEvents.Type.FAMILY_OUTING);return;}if(parts[0].equals("subtype")){try{s.loop.event.putString("ForcedOuting",Subtype.valueOf(arg).name());VisitEvents.start(p,s,VisitEvents.Type.FAMILY_OUTING);}catch(IllegalArgumentException ignored){}return;}if(VisitEvents.type(s)!=VisitEvents.Type.FAMILY_OUTING)return;var n=s.loop.event;switch(parts[0]){case "destination"->{var site=OutingSites.current(s);if(site!=null){var at=site.arrival();p.teleportTo(p.serverLevel(),at.getX()+.5,at.getY(),at.getZ()+.5,p.getYRot(),0);}}case "window"->beginWindow(p,s);case "late"->{n.putInt("ArrivalRemaining",0);n.putBoolean("GraceRolled",true);n.putInt("GraceRemaining",1200);}case "grace"->{n.putInt("ArrivalRemaining",0);n.putBoolean("GraceRolled",true);n.putInt("GraceRemaining",0);}case "resume"->resume(p);case "active"->beginExperience(p,s);case "finish"->{release(p,s);OtherMotherLoop.phase(p,s,OUTING_FINISH);}case "reward"->reward(p,s);case "voice"->{try{int index=Integer.parseInt(arg);var pools=pools();if(index>=0&&index<60)VisitAudio.play(p,pools.get(index/2).sound(index%2),false);else if(index>=60&&index<75)VisitAudio.play(p,fatherVoices().get(index-60),false);}catch(NumberFormatException ignored){}}case "state"->p.sendSystemMessage(Component.literal(n.toString()));default->{}}OtherMotherLoop.changed(p);}
    private FamilyOuting(){}
}
